  /**
   * Initialize guest checkout session
   */
  const initializeSession = useCallback(async (guestId?: string, sessionId?: string, cartId?: string) => {
    setIsLoading(true);
    setError(null);

    try {
      // Check for existing guest session in localStorage
      const existingSessionId = localStorage.getItem(GUEST_SESSION_KEY);
      
      // Note: cartId is not passed for guest users because:
      // 1. Guest carts use sessionId as identifier, not UUID cartId
      // 2. Backend can derive the cart from sessionId
      // 3. This avoids validation errors when cartId is not a valid UUID
      const request: InitializeGuestCheckoutRequest = {
        guestId,
        sessionId: sessionId || existingSessionId || undefined,
        cartId: undefined,  // Don't pass cartId for guest users - let backend derive from sessionId
        platform: typeof window !== 'undefined' && window.innerWidth < 768 ? 'mobile' : 'desktop',
        language: 'en', // Will be fetched from language context
      };

  // Redirect if cart is empty
  useEffect(() => {
    // Add a small delay to allow cart to load from localStorage
    const timer = setTimeout(() => {
      if (!isInitializing && items.length === 0 && !isLoading) {
        toast.error('Your cart is empty');
        router.push('/cart');
      }
    }, 500); // 500ms delay to allow cart initialization to complete

    return () => clearTimeout(timer);
  }, [items.length, isLoading, isInitializing, router]);

